<?php

// Generated by Polka. Re-run Composer through Polka after editing database or Mailpit settings.
$databases['default']['default'] = [
  'database' => {{database}},
  'username' => {{username}},
  'password' => {{password}},
  'prefix' => '',
  'host' => {{host}},
  'port' => {{port}},
  'namespace' => {{namespace}},
  'driver' => {{driver}},
  'autoload' => {{autoload}},
];

// Mailer Plus 2.x uses mailer_transport; Symfony Mailer 1.x uses symfony_mailer.
// Override the existing sendmail transport locally without exporting changes.
if ({{mailpit-enabled}}) {
  foreach (['symfony_mailer', 'mailer_transport'] as $polkaMailer) {
    $config[$polkaMailer . '.settings']['default_transport'] = 'sendmail';
    $config[$polkaMailer . '.mailer_transport.sendmail']['plugin'] = 'smtp';
    $config[$polkaMailer . '.mailer_transport.sendmail']['configuration'] = [
      'user' => '',
      'pass' => '',
      'host' => '127.0.0.1',
      'port' => {{mailpit-port}},
      // Mailpit can advertise STARTTLS with Polka's local certificate.
      'query' => ['verify_peer' => false],
    ];
  }
  unset($polkaMailer);
}
